import{_ as n}from"./chunks/projects.BdG50VF9.js";import{_ as i,c as r,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"Vor dem Commit","description":"Prüfen Sie jede geänderte Datei in einem Projektordner und führen Sie den Commit aus, ohne qDiff zu verlassen.","frontmatter":{"title":"Vor dem Commit","description":"Prüfen Sie jede geänderte Datei in einem Projektordner und führen Sie den Commit aus, ohne qDiff zu verlassen."},"headers":[],"relativePath":"de/guide/projects.md","filePath":"de/guide/projects.md","lastUpdated":1794296122000}'),s={name:"de/guide/projects.md"};function d(o,e,l,h,m,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="vor-dem-commit" tabindex="-1">Vor dem Commit <a class="header-anchor" href="#vor-dem-commit" aria-label="Permalink to &quot;Vor dem Commit&quot;">​</a></h1><p>Ein kurzes „Was habe ich eigentlich geändert?“ ist vor jedem Commit sinnvoll. Öffnen Sie einen Projektordner in qDiff, und die Antwort liegt bereits bereit.</p><img src="'+n+'" alt="Eine Liste geänderter Dateien neben einem farbig markierten Diff" class="guide-shot"><h2 id="einen-projektordner-offnen" tabindex="-1">Einen Projektordner öffnen <a class="header-anchor" href="#einen-projektordner-offnen" aria-label="Permalink to &quot;Einen Projektordner öffnen&quot;">​</a></h2><p>Wählen Sie den Ordner eines Git-Projekts über <strong>Ablage → Öffnen</strong> aus oder ziehen Sie ihn ins Fenster. qDiff fasst die Dateien, die Sie bearbeitet haben, in einer Liste zusammen.</p><h2 id="erst-die-liste-dann-die-anderungen" tabindex="-1">Erst die Liste, dann die Änderungen <a class="header-anchor" href="#erst-die-liste-dann-die-anderungen" aria-label="Permalink to &quot;Erst die Liste, dann die Änderungen&quot;">​</a></h2><p>Jede Datei ist danach gekennzeichnet, was mit ihr geschehen ist: neu, geändert oder entfernt. Klicken Sie eine an, und rechts sehen Sie genau, was sich darin geändert hat — mit denselben Farben und Hervorhebungen auf Wortebene wie bei einem normalen Dateivergleich.</p><p>Arbeiten Sie sie eine nach der anderen durch — die Liste merkt sich Ihre Position, sodass bei einer langen Prüfung nichts übersprungen wird.</p><h2 id="im-selben-fenster-abschließen" tabindex="-1">Im selben Fenster abschließen <a class="header-anchor" href="#im-selben-fenster-abschließen" aria-label="Permalink to &quot;Im selben Fenster abschließen&quot;">​</a></h2><p>Wenn alles stimmt, führen Sie den Commit von hier aus. Sie können auch aktualisieren, pushen, zurücksetzen oder einen Konflikt lösen, ohne den Vergleich zu verlassen. Es muss keine andere App geöffnet sein, und ein Konto ist nicht erforderlich.</p><div class="tip custom-block"><p class="custom-block-title">Kein Projektordner?</p><p>Jeder gewöhnliche Ordner öffnet sich weiterhin als normaler Ordnervergleich — <a href="./folders.html">Ordner vergleichen</a> funktioniert überall.</p></div><p>Weiter: <a href="./more.html">Bilder, Archive und mehr</a>.</p>',12)])])}const b=i(s,[["render",d]]);export{p as __pageData,b as default};
